function openForgot(){openModal('Reset password',`<div class="alert info">Demo verification: enter the username and the registered email or mobile number. A production backend should use OTP/email verification and rate limiting.</div><div class="form-grid"><label>Username<input id="fpUser"></label><label>Registered email or mobile<input id="fpVerify" placeholder="Email or 07XXXXXXXX"></label><label>New password<input id="fpPass" type="password"></label></div>`,`<button class="small-btn" data-close>Cancel</button><button class="primary-btn" id="resetPass">Reset password</button>`);$('#resetPass').onclick=()=>{const db=getDB(),u=db.users.find(x=>x.username.toLowerCase()===$('#fpUser').value.trim().toLowerCase());if(!u)return toast('User not found','error');const verify=$('#fpVerify').value.trim().toLowerCase(),email=String(u.email||'').toLowerCase(),phone=normalizePhone(u.phone||'').toLowerCase();if(!verify||!(verify===email||normalizePhone(verify).toLowerCase()===phone))return toast('Verification details do not match','error');if($('#fpPass').value.length<8)return toast('Password must be 8+ characters','error');u.password=$('#fpPass').value;saveDB(db);DB.addAudit('Password reset after identity check','self',u.id);closeModal();toast('Password reset successfully')}}
function openBooking(id){const d=DB.getDoctor(id);if(!d?.available)return toast('Doctor is unavailable','error');const min=new Date();min.setDate(min.getDate()+1);const def=localDateISO(min);const getSlots=date=>{const sch=DB.getDoctorSchedule(id,date);if((sch?.available===false)||(d.leaveDates||[]).includes(date))return [];return (sch?.slots||[]).filter(t=>!DB.appointments.some(a=>a.doctorId===id&&a.date===date&&a.time===t&&a.status!=='cancelled'));};openModal('Book with '+d.name,`<div class="alert info">SLMC ${esc(d.regNo)} · ${esc(d.specialty)} · ${money(d.fee)} + platform fee ${money(150)}</div><div class="form-grid"><label>Date<input id="bookDate" type="date" min="${def}" value="${def}"></label><label>Available time<select id="bookTime"></select></label><label class="full-col">Reason / symptoms<textarea id="bookReason" rows="3"></textarea></label></div><div class="payment-box"><div class="payment-row"><span>Consultation</span><b>${money(d.fee)}</b></div><div class="payment-row"><span>Platform fee</span><b>${money(150)}</b></div><div class="payment-row payment-total"><span>Total</span><b>${money(d.fee+150)}</b></div></div>`,`<button class="small-btn" id="clearBooking">Clear all</button><button class="small-btn" data-close>Cancel</button><button class="primary-btn" id="confirmBooking">Continue to payment →</button>`);const fillSlots=()=>{const slots=getSlots($('#bookDate').value);$('#bookTime').innerHTML=slots.map(s=>`<option value="${s}">${fmtTime(s)}</option>`).join('')||'<option value="">No available time</option>';};$('#bookDate').onchange=fillSlots;fillSlots();$('#clearBooking').onclick=()=>{$('#bookDate').value=def;fillSlots();$('#bookReason').value='';toast('Appointment form cleared')};$('#confirmBooking').onclick=()=>{const date=$('#bookDate').value,time=$('#bookTime').value;if(!time)return toast('No available time slot for this date','error');if(!getSlots(date).includes(time))return toast('That slot is no longer available','error');let ap;try{ap=DB.createAppointment({patientId:state.user.patientId,doctorId:id,date,time,reason:$('#bookReason').value.trim()||'General consultation',amount:d.fee+150})}catch(e){return toast(e.message||'Unable to create appointment','error')}DB.addNotification({userId:state.user.id,title:'Booking created',message:`${ap.id} with ${d.name} is pending payment. Queue #${ap.queue}.`});closeModal();openPayment(ap.id)}}
function openAdminCashPayment(id){const a=DB.appointments.find(x=>x.id===id),d=DB.getDoctor(a?.doctorId),p=DB.getPatient(a?.patientId);if(!a)return;if(state.user.role!=='admin')return toast('Admin cashier access required','error');if(a.paymentStatus==='paid')return toast('This appointment is already paid','error');if(a.paymentStatus==='pending_verification')return toast('Bank transfer is awaiting verification','error');openModal('Cash payment — Admin cashier',`<div class="alert info"><b>Cash only</b> · Card and Bank Transfer are not available in the Admin cashier.</div><div class="payment-box"><div class="payment-row"><span>Patient</span><b>${esc(p?.name||a.patientName||'Walk-in patient')}</b></div><div class="payment-row"><span>Doctor</span><b>${esc(d?.name||'—')}</b></div><div class="payment-row payment-total"><span>Total payable</span><b>${money(a.amount)}</b></div></div><div class="form-grid"><label>Cash received<input id="adminCashReceived" type="number" min="${a.amount}" step="0.01" placeholder="Enter cash received"></label><label>Cash reference<input id="adminCashRef" value="CASH-${Date.now()}" placeholder="Cash reference"></label></div><div class="change-card"><span>Balance / Change</span><strong id="adminCashChange">LKR 0</strong></div>`,`<button class="small-btn" data-close>Cancel</button><button class="primary-btn" id="confirmAdminCash">Confirm Cash Payment</button>`);const received=$('#adminCashReceived');const change=()=>{$('#adminCashChange').textContent=money(Math.max(0,Number(received.value||0)-Number(a.amount||0)))};received.oninput=change;$('#confirmAdminCash').onclick=()=>{const cash=Number(received.value||0);if(!Number.isFinite(cash)||cash<a.amount)return toast(`Cash received must be at least ${money(a.amount)}`,'error');const ref=$('#adminCashRef').value.trim()||`CASH-${Date.now()}`;DB.updateAppointment(id,{paymentStatus:'paid',paymentMethod:'Cash',paymentRef:ref,cashReceived:cash,balanceReturned:cash-a.amount,status:'confirmed'});markRecordActioned('appointments',id);const db=getDB();const existing=(db.payments||[]).find(x=>x.appointmentId===id&&x.status!=='refunded');if(existing){Object.assign(existing,{amount:a.amount,method:'Cash',status:'paid',reference:ref,cashReceived:cash,balanceReturned:cash-a.amount,verifiedBy:state.user.id,verifiedAt:new Date().toISOString()});saveDB(db)}else DB.addPayment({appointmentId:id,patientId:a.patientId,amount:a.amount,method:'Cash',status:'paid',reference:ref,cashReceived:cash,balanceReturned:cash-a.amount,verifiedBy:state.user.id});markRecordActioned('payments',id);const cashDb=getDB();const cashInv=cashDb.invoices.find(x=>x.appointmentId===id);if(cashInv){cashInv.amountReceived=Math.min(Number(cashInv.total||a.amount)||0,a.amount);cashInv.balance=0;cashInv.change=Math.max(0,cash-a.amount);cashInv.status='paid';cashInv.paymentMethod='Cash';cashInv.paymentRef=ref;saveDB(cashDb)}else DB.createInvoice({...a,paymentStatus:'paid',paymentMethod:'Cash',paymentRef:ref,cashReceived:cash,balanceReturned:Math.max(0,cash-a.amount)});DB.addAudit('Cash payment recorded','admin',id);const pu=db.users.find(u=>u.patientId===a.patientId);if(pu)DB.addNotification({userId:pu.id,title:'Cash payment recorded',message:`Cash payment for ${id} was recorded. Change: ${money(cash-a.amount)}.`});closeModal();toast('Cash payment confirmed ✓');render()}}
function openPayment(id){const a=DB.appointments.find(x=>x.id===id),d=DB.getDoctor(a?.doctorId);if(!a)return;if(state.user.role!=='patient'||a.patientId!==state.user.patientId)return toast('Only the booked patient can make this payment','error');if(a.status==='cancelled'||a.status==='completed')return toast('This appointment can no longer be paid','error');if(a.paymentStatus==='paid')return toast('This appointment is already paid','error');openModal('Complete payment',`<div class="alert info">Patient payments: Card or Bank Transfer. Cash is handled only by the Admin cashier.</div><div class="payment-box"><div class="payment-row"><span>Appointment</span><b>${a.id}</b></div><div class="payment-row"><span>Doctor</span><b>${esc(d?.name||'—')}</b></div><div class="payment-row payment-total"><span>Total payable</span><b>${money(a.amount)}</b></div></div><div class="form-grid"><label>Payment method<select id="payMethod"><option>Card</option><option>Bank Transfer</option></select></label><label>Transaction / reference<input id="payRef" placeholder="Reference number" maxlength="40"></label><label class="full-col" id="cardHolderWrap">Cardholder name<input id="cardHolder" autocomplete="cc-name" maxlength="80" placeholder="Name as shown on card"></label><label id="cardNumberWrap">Card number<input id="cardNumber" inputmode="numeric" autocomplete="cc-number" maxlength="23" placeholder="4111 1111 1111 1111"></label><label id="cardExpiryWrap">Expiry<input id="cardExpiry" inputmode="numeric" autocomplete="cc-exp" placeholder="MM/YY" maxlength="5"></label><label id="cardCvvWrap">CVV<input id="cardCvv" type="password" inputmode="numeric" autocomplete="cc-csc" maxlength="4" placeholder="123"></label><label class="full-col" id="proofWrap">Bank transfer receipt<input id="payProof" type="file" accept="image/png,image/jpeg,image/webp,application/pdf"><small class="sub">Required for Bank Transfer · max 3MB.</small></label></div><div class="validation-hint" id="cardValidationHint">Card checks: card number, expiry date, CVV and cardholder name.</div><div class="clear-strip"><button type="button" class="small-btn" id="clearPaymentForm">Clear fields</button></div>`,`<button class="small-btn" data-close>Cancel</button><button class="primary-btn" id="payNow">Submit payment</button>`);const method=$('#payMethod'),proof=$('#payProof'),num=$('#cardNumber'),exp=$('#cardExpiry'),cvv=$('#cardCvv'),holder=$('#cardHolder'),ref=$('#payRef');const setValid=(el,ok)=>{if(!el)return;el.classList.toggle('field-valid',!!ok);el.classList.toggle('field-invalid',!ok&&el.value.trim()!=='')};const sync=()=>{const bank=method.value==='Bank Transfer';$('#proofWrap').style.display=bank?'block':'none';$('#cardNumberWrap').style.display=bank?'none':'block';$('#cardExpiryWrap').style.display=bank?'none':'block';$('#cardCvvWrap').style.display=bank?'none':'block';$('#cardHolderWrap').style.display=bank?'none':'block';$('#cardValidationHint').style.display=bank?'none':'block'};method.onchange=sync;num?.addEventListener('input',()=>{num.value=formatCardNumber(num.value);setValid(num,luhnValid(num.value))});exp?.addEventListener('input',()=>{let v=exp.value.replace(/\D/g,'').slice(0,4);if(v.length>2)v=v.slice(0,2)+'/'+v.slice(2);exp.value=v;setValid(exp,cardExpiryValid(v))});cvv?.addEventListener('input',()=>{cvv.value=cvv.value.replace(/\D/g,'').slice(0,4);setValid(cvv,/^\d{3,4}$/.test(cvv.value))});holder?.addEventListener('input',()=>setValid(holder,/^[\p{L}][\p{L} .'-]{2,79}$/u.test(holder.value.trim())));ref?.addEventListener('input',()=>setValid(ref,/^[A-Za-z0-9][A-Za-z0-9._/-]{3,39}$/.test(ref.value.trim())));$('#clearPaymentForm').onclick=()=>{[ref,num,exp,cvv,holder].forEach(x=>{if(x)x.value=''});if(proof)proof.value='';sync()};sync();$('#payNow').onclick=()=>{const m=method.value,r=ref.value.trim(),file=proof.files?.[0];if(!r||!/^\S{4,40}$/.test(r))return toast('Enter a valid payment reference (4–40 characters)','error');if(m==='Bank Transfer'){if(!file)return toast('Upload the bank transfer receipt','error');if(!['image/png','image/jpeg','image/webp','application/pdf'].includes(file.type))return toast('Receipt must be PNG, JPG, WebP or PDF','error');if(file.size>3*1024*1024)return toast('Receipt must be under 3MB','error');}else{if(!/^[\p{L}][\p{L} .'-]{2,79}$/u.test(holder.value.trim()))return toast('Enter a valid cardholder name','error');if(!luhnValid(num.value))return toast('Card number is invalid','error');if(!cardExpiryValid(exp.value))return toast('Card expiry must be a valid future month','error');if(!/^\d{3,4}$/.test(cvv.value))return toast('CVV must be 3 or 4 digits','error')}const save=proofData=>{const status=m==='Bank Transfer'?'pending_verification':'paid';DB.updateAppointment(id,{paymentStatus:status,paymentMethod:m,paymentRef:r,paymentProof:proofData,cardHolder:m==='Card'?holder.value.trim():undefined,status:m==='Bank Transfer'?'pending':'confirmed'});markRecordActioned('appointments',id);DB.addPayment({appointmentId:id,patientId:a.patientId,amount:a.amount,method:m,status,reference:r,proof:proofData,cardHolder:m==='Card'?holder.value.trim():undefined});markRecordActioned('payments',id);if(m==='Card'){const dbPay=getDB();let inv=dbPay.invoices.find(x=>x.appointmentId===id);if(!inv)inv=DB.createInvoice({...a,paymentStatus:'paid',paymentMethod:m,paymentRef:r});else{const total=Math.max(0,Number(inv.total||a.amount)||0);inv.amountReceived=Math.min(total,a.amount);inv.balance=Math.max(0,total-inv.amountReceived);inv.status='paid';inv.paymentMethod=m;inv.paymentRef=r;saveDB(dbPay)}}DB.addNotification({userId:state.user.id,title:m==='Bank Transfer'?'Payment submitted':'Card payment recorded',message:m==='Bank Transfer'?`Receipt uploaded for ${id}. Admin verification is pending.`:`Card payment for ${id} was recorded.`});const au=DB.users.find(u=>u.role==='admin');if(au)DB.addNotification({userId:au.id,title:m==='Bank Transfer'?'Payment verification required':'Card payment received',message:`${id} · ${m} · ${r}`});closeModal();toast(m==='Bank Transfer'?'Receipt submitted ✓':'Card payment recorded ✓');render()};if(file){const r=new FileReader();r.onload=()=>save(r.result);r.readAsDataURL(file)}else save('')}}
function openPaymentVerification(id){const a=DB.appointments.find(x=>x.id===id);if(state.user.role!=='admin')return toast('Admin access required','error');if(!a||a.paymentStatus!=='pending_verification')return toast('No pending payment verification','error');const p=DB.getPatient(a.patientId),d=DB.getDoctor(a.doctorId),proof=a.paymentProof||'';const isPdf=proof.startsWith('data:application/pdf');const proofView=isPdf?`<iframe src="${proof}" style="width:100%;height:420px;border:1px solid #dfe5ef;border-radius:12px"></iframe>`:`<img src="${proof}" alt="Bank transfer receipt" style="width:100%;max-height:460px;object-fit:contain;border:1px solid #dfe5ef;border-radius:12px">`;openModal('Verify bank transfer',`<div class="alert info"><b>${esc(a.paymentRef||'No reference')}</b> · ${money(a.amount)}</div><p><b>Patient:</b> ${esc(p?.name||a.patientName||'Walk-in patient')}<br><b>Doctor:</b> ${esc(d?.name)}<br><b>Appointment:</b> ${a.id} · ${fmtDate(a.date)} ${fmtTime(a.time)}</p>${proofView}`,`<button class="small-btn" data-close>Close</button><button class="primary-btn" id="confirmBankPayment">Confirm payment</button>`);$('#confirmBankPayment').onclick=()=>{const db=getDB();const pay=(db.payments||[]).find(x=>x.appointmentId===id&&x.status==='pending_verification');DB.updateAppointment(id,{paymentStatus:'paid',status:'confirmed'});markRecordActioned('appointments',id);if(pay){Object.assign(pay,{status:'paid',verifiedBy:state.user.id,verifiedAt:new Date().toISOString()});saveDB(db)}else DB.addPayment({appointmentId:id,patientId:a.patientId,amount:a.amount,method:'Bank Transfer',status:'paid',reference:a.paymentRef,proof:a.paymentProof,verifiedBy:state.user.id,verifiedAt:new Date().toISOString()});markRecordActioned('payments',id);const db2=getDB();const inv=db2.invoices.find(x=>x.appointmentId===id);if(inv){const total=Math.max(0,Number(inv.total||a.amount)||0);inv.amountReceived=Math.min(total,Number(a.amount)||0);inv.balance=Math.max(0,total-inv.amountReceived);inv.status='paid';inv.paymentMethod='Bank Transfer';inv.paymentRef=a.paymentRef;saveDB(db2)}else DB.createInvoice({...a,paymentStatus:'paid',paymentMethod:'Bank Transfer',paymentRef:a.paymentRef});DB.addAudit('Bank transfer verified','admin',id);DB.addNotification({userId:(getDB().users.find(u=>u.patientId===a.patientId)?.id||''),title:'Bank transfer confirmed',message:`Your payment for ${id} has been verified.`});closeModal();toast('Payment confirmed ✓');render()}}
function rejectPayment(id){const a=DB.appointments.find(x=>x.id===id);if(state.user.role!=='admin'||!a||a.paymentStatus!=='pending_verification')return toast('No pending payment to reject','error');const reason=prompt('Reason for rejecting this bank transfer:','Receipt could not be verified');if(reason===null)return;const db=getDB();const pay=(db.payments||[]).find(x=>x.appointmentId===id&&x.status==='pending_verification');if(pay){pay.status='rejected';pay.rejectedBy=state.user.id;pay.rejectedAt=new Date().toISOString();pay.rejectionReason=reason.trim()||'Receipt could not be verified'}markRecordActioned('payments',id);DB.updateAppointment(id,{paymentStatus:'unpaid',paymentMethod:'',paymentRef:'',paymentProof:'',status:a.status==='confirmed'?'pending':a.status});markRecordActioned('appointments',id);const pu=db.users.find(u=>u.patientId===a.patientId);if(pu)DB.addNotification({userId:pu.id,title:'Payment rejected',message:`Your bank transfer for ${id} was rejected. Reason: ${reason.trim()||'Receipt could not be verified'}. Please submit a valid receipt.`});DB.addAudit('Bank transfer rejected','admin',id);toast('Payment rejected');render()}
function openRefund(id){const a=DB.appointments.find(x=>x.id===id);if(!a||a.paymentStatus!=='paid')return toast('Only paid appointments can be refunded','error');openModal('Refund payment',`<div class="alert info">Create a refund request for ${esc(a.id)}. In production, the backend/payment gateway should process the actual refund.</div><div class="payment-box"><div class="payment-row"><span>Refund amount</span><b>${money(a.amount)}</b></div></div><label>Reason<textarea id="refundReason" rows="3" placeholder="Reason for refund"></textarea></label>`,`<button class="small-btn" data-close>Cancel</button><button class="primary-btn danger-soft" id="doRefund">Create refund request</button>`);$('#doRefund').onclick=()=>{const reason=$('#refundReason').value.trim()||'Admin refund request';DB.addRefund({appointmentId:id,patientId:a.patientId,amount:a.amount,reason,requestedBy:state.user.id});markRecordActioned('appointments',id);markRecordActioned('payments',id);DB.addAudit('Refund requested','admin',id);DB.addNotification({userId:(getDB().users.find(u=>u.patientId===a.patientId)?.id||''),title:'Refund requested',message:`A refund request was created for ${id}.`});closeModal();toast('Refund request created');render()}}
function openReceipt(id){markRecordActioned('appointments',id);markRecordActioned('payments',id);const a=DB.appointments.find(x=>x.id===id);if(!a)return;const p=DB.getPatient(a.patientId),d=DB.getDoctor(a.doctorId),patientName=p?.name||a.patientName||'Walk-in patient';openModal('Payment receipt',`<div class="receipt"><h3>MediFlow</h3><p>Official demo payment receipt</p><hr><p><b>Transaction:</b> TX-${a.id}</p><p><b>Appointment:</b> ${a.id} · Queue #${a.queue}</p><p><b>Patient:</b> ${esc(patientName)}</p><p><b>Doctor:</b> ${esc(d?.name||'Doctor record unavailable')}</p><p><b>Date:</b> ${fmtDate(a.date)} ${fmtTime(a.time)}</p><p><b>Method:</b> ${esc(a.paymentMethod)}</p><h2>${money(a.amount)}</h2></div>`,`<button class="primary-btn" data-close>Close</button>`)}
function openDoctorForm(id){const d=id?DB.getDoctor(id):{name:'',specialty:'General Physician',regNo:'',phone:'',email:'',fee:2500,experience:1,username:'dr.new',password:'Doctor@123',location:'Colombo',bio:'',available:true,photo:''};openModal(id?'Edit doctor':'Add doctor',`<div class="doctor-photo-editor"><div id="doctorPhotoPreview">${avatar(d,'doc-avatar big')}</div><div><b>Doctor profile photo</b><small>JPG/PNG/WebP · preview before saving</small><input id="dPhoto" type="file" accept="image/png,image/jpeg,image/webp"><button type="button" class="small-btn" id="clearDoctorPhoto">Remove photo</button></div></div><div class="form-grid"><label>Full name<input id="dName" value="${esc(d.name)}"></label><label>Specialty<select id="dSpecialty">${DB.specialties.map(s=>`<option ${d.specialty===s?'selected':''}>${esc(s)}</option>`).join('')}</select></label><label>SLMC registration<input id="dReg" value="${esc(d.regNo)}" placeholder="SLMC-12345"></label><label>Registered phone<input id="dPhone" value="${esc(d.phone)}" placeholder="07XXXXXXXX"></label><label>Email<input id="dEmail" type="email" value="${esc(d.email)}"></label><label>Fee<input id="dFee" type="number" value="${d.fee}"></label><label>Experience<input id="dExp" type="number" value="${d.experience}"></label><label>Location<input id="dLocation" value="${esc(d.location)}"></label>${!id?`<label>Username<input id="dUsername" value="${esc(d.username)}"></label><label>Password<input id="dPassword" type="password" value="${d.password||'Doctor@123'}"></label>`:''}<label class="full-col">Bio<textarea id="dBio" rows="3">${esc(d.bio)}</textarea></label></div><div class="clear-strip"><button type="button" class="small-btn" id="clearDoctorForm">Clear fields</button></div><div class="alert info">Doctor phone and SLMC registration are required. Login credentials are created automatically for new doctors.</div>`,`<button class="small-btn" data-close>Cancel</button><button class="primary-btn" id="saveDoctor">Save doctor</button>`);let photo=d.photo||'';$('#dPhoto').onchange=e=>{const f=e.target.files?.[0];if(!f)return;if(f.size>2*1024*1024)return toast('Photo must be under 2MB','error');const r=new FileReader();r.onload=()=>{photo=r.result;$('#doctorPhotoPreview').innerHTML=avatar({name:d.name,photo},'doc-avatar big')};r.readAsDataURL(f)};$('#clearDoctorPhoto').onclick=()=>{photo='';$('#dPhoto').value='';$('#doctorPhotoPreview').innerHTML=avatar({name:$('#dName').value||'Doctor'},'doc-avatar big')};$('#clearDoctorForm').onclick=()=>{$$(`#modalRoot input:not([type=file]), #modalRoot textarea`).forEach(x=>x.value='');$('#dFee').value='2500';$('#dExp').value='1'};$('#saveDoctor').onclick=()=>{const phone=normalizePhone($('#dPhone').value.trim()),reg=$('#dReg').value.trim(),fee=Number($('#dFee').value),experience=Number($('#dExp').value);if(!$('#dName').value.trim()||!$('#dEmail').value.trim())return toast('Complete required fields','error');if(!validatePhone(phone))return toast('Invalid Sri Lankan phone','error');if(!/^SLMC[- ]?\d{4,8}$/i.test(reg))return toast('Invalid SLMC registration','error');if(!Number.isFinite(fee)||fee<=0)return toast('Doctor fee must be greater than 0','error');if(!Number.isFinite(experience)||experience<0)return toast('Experience cannot be negative','error');const data={photo,name:$('#dName').value.trim(),specialty:$('#dSpecialty').value,regNo:reg,phone,email:$('#dEmail').value.trim(),fee,experience,location:$('#dLocation').value.trim(),bio:$('#dBio').value.trim(),available:id?d.available:true,leaveDates:d.leaveDates||[]};if(id){try{DB.updateDoctor(id,data);DB.addAudit('Doctor profile updated','admin',id);toast('Doctor updated')}catch(e){return toast(e.message||'Unable to update doctor','error')}}else{const un=$('#dUsername').value.trim(),pw=$('#dPassword').value;if(!un||!pw)return toast('Username and password are required','error');if(DB.users.some(u=>u.username.toLowerCase()===un.toLowerCase()))return toast('Username exists','error');data.username=un;data.password=pw;try{DB.addDoctor(data);DB.addAudit('Doctor created','admin',un);toast('Doctor created')}catch(e){return toast(e.message||'Unable to create doctor','error')}}closeModal();render()}}
function openScheduleForm(id,date){const d=DB.getDoctor(id);const e=(d.schedules||[]).find(s=>s.date===date)||{date:date||'',from:d.workingHours?.from||'08:00',to:d.workingHours?.to||'17:00',slots:[],available:true};openModal(date?'Edit schedule':'Add date schedule',`<div class="form-grid"><label>Date<input id="schDate" type="date" min="${today()}" value="${e.date}"></label><label>Status<select id="schAvailable"><option value="true" ${e.available!==false?'selected':''}>Available</option><option value="false" ${e.available===false?'selected':''}>Unavailable</option></select></label><label>Working from<input id="schFrom" type="time" value="${e.from}"></label><label>Working until<input id="schTo" type="time" value="${e.to}"></label><div class="full-col"><label>Add time slot<input id="newSlotTime" type="time"><button type="button" class="small-btn blue" id="addSlotBtn" style="margin-top:8px">+ Add slot</button></label><div id="slotChips" class="tag-row" style="margin-top:10px"></div><small class="sub">Default: 30-minute slots are generated from working hours. Remove any slot you don't need.</small></div></div><div class="alert info">Example: 08:00 – 17:00 creates 08:00, 08:30, 09:00 ... 16:30.</div>`,`<button class="small-btn" data-close>Cancel</button><button class="primary-btn" id="saveSchedule">Save schedule</button>`);let slots=[...new Set(e.slots||[])].sort();const renderSlots=()=>{$('#slotChips').innerHTML=slots.length?slots.map(t=>`<span class="tag slot-chip">${fmtTime(t)} <button type="button" class="icon-btn" data-removeslot="${t}" title="Remove slot">×</button></span>`).join(''):'<span class="sub">No slots configured</span>';$$('[data-removeslot]').forEach(b=>b.onclick=()=>{slots=slots.filter(x=>x!==b.dataset.removeslot);renderSlots()})};const autoGenerate=()=>{const from=$('#schFrom').value,to=$('#schTo').value;if(!from||!to||from>=to)return;const [fh,fm]=from.split(':').map(Number),[th,tm]=to.split(':').map(Number);let cur=fh*60+fm,end=th*60+tm;slots=[];while(cur<end){slots.push(`${String(Math.floor(cur/60)).padStart(2,'0')}:${String(cur%60).padStart(2,'0')}`);cur+=30;}renderSlots()};renderSlots();$('#schFrom').onchange=()=>{if(!slots.length)autoGenerate()};$('#schTo').onchange=()=>{if(!slots.length)autoGenerate()};$('#addSlotBtn').onclick=()=>{const t=$('#newSlotTime').value,from=$('#schFrom').value,to=$('#schTo').value;if(!t)return toast('Choose a time slot','error');if(t<from||t>=to)return toast('Slot must be inside working hours','error');if(slots.includes(t))return toast('That slot already exists','error');slots.push(t);slots.sort();$('#newSlotTime').value='';renderSlots()};if(!slots.length)autoGenerate();$('#saveSchedule').onclick=()=>{const newDate=$('#schDate').value,from=$('#schFrom').value,to=$('#schTo').value,available=$('#schAvailable').value==='true';if(!newDate||!from||!to)return toast('Complete date and working hours','error');if(from>=to)return toast('End time must be after start time','error');slots=[...new Set(slots)].sort();if(slots.some(t=>!/^(?:[01]\d|2[0-3]):[0-5]\d$/.test(t)||t<from||t>=to))return toast('Every slot must be a valid time inside the working hours','error');if(newDate!==e.date&&e.date)DB.removeDoctorSchedule(id,e.date);DB.setDoctorSchedule(id,{date:newDate,from,to,available,slots});DB.addAudit('Doctor schedule updated',state.user.role,id);closeModal();toast('Schedule saved ✓');render()}}
function removeSchedule(id,date){if(!confirm('Remove this date schedule?'))return;DB.removeDoctorSchedule(id,date);DB.addAudit('Doctor schedule removed',state.user.role,id);toast('Schedule removed');render()}
function openLeave(id){const d=DB.getDoctor(id);openModal('Doctor leave dates',`<div class="alert info">Add a date when this doctor will not accept appointments. New appointments will be blocked on this date. Existing appointments are kept unchanged.</div><label>Leave date<input id="leaveDate" type="date" min="${today()}"></label>`,`<button class="small-btn" data-close>Cancel</button><button class="primary-btn" id="saveLeave">Add leave</button>`);$('#saveLeave').onclick=()=>{const date=$('#leaveDate').value;if(!date)return toast('Select a date','error');const dates=[...(d.leaveDates||[])];if(!dates.includes(date))dates.push(date);DB.updateDoctor(id,{leaveDates:dates.sort()});DB.addAudit('Doctor leave added',state.user.role,id);closeModal();toast('Leave date added');render()}}
function removeLeave(id,date){const d=DB.getDoctor(id);if(!d)return;DB.updateDoctor(id,{leaveDates:(d.leaveDates||[]).filter(x=>x!==date)});toast('Leave removed');render()}
function saveProfile(){const phone=normalizePhone($('#profilePhone').value.trim()),name=$('#profileName').value.trim(),email=$('#profileEmail').value.trim();if(!validatePhone(phone))return toast('Invalid Sri Lankan mobile number','error');if(!name||!email)return toast('Name and email are required','error');const db=getDB(),u=db.users.find(x=>x.id===state.user.id);Object.assign(u,{name,phone,email});if(u.role==='patient'){const p=db.patients.find(x=>x.id===u.patientId);Object.assign(p,{name,phone,email,address:$('#profileAddress')?.value||p.address})}if(u.role==='doctor'){const d=db.doctors.find(x=>x.id===u.doctorId);Object.assign(d,{name,phone,email})}saveDB(db);state.user=clone(u);sessionStorage.setItem('mediflow_user',JSON.stringify(state.user));toast('Profile updated');showApp()}
function changePassword(){openModal('Change password',`<label>New password<input id="newPass" type="password" placeholder="Minimum 8 characters"></label>`,`<button class="small-btn" data-close>Cancel</button><button class="primary-btn" id="savePass">Save</button>`);$('#savePass').onclick=()=>{if($('#newPass').value.length<8)return toast('Password must be 8+ characters','error');const db=getDB(),u=db.users.find(x=>x.id===state.user.id);u.password=$('#newPass').value;saveDB(db);closeModal();toast('Password changed')}}
function exportReport(){const rows=[['Appointment','Patient','Doctor','Date','Time','Status','Payment','Amount'],...DB.appointments.map(a=>[a.id,DB.getPatient(a.patientId)?.name,DB.getDoctor(a.doctorId)?.name,a.date,a.time,a.status,a.paymentStatus,a.amount])];const csv=rows.map(r=>r.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(',')).join('\n');const blob=new Blob([csv],{type:'text/csv'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='mediflow-report.csv';a.click();URL.revokeObjectURL(url);toast('Report exported')}
function openReschedule(id){
 const a=DB.appointments.find(x=>x.id===id); if(!a)return;
 if(state.user.role!=='patient'||a.patientId!==state.user.patientId)return toast('Only the appointment owner can reschedule','error');
 if(['cancelled','completed'].includes(a.status))return toast('This appointment cannot be rescheduled','error');
 const d=DB.getDoctor(a.doctorId); if(!d)return toast('Doctor not found','error');
 const min=new Date(); min.setDate(min.getDate()+1); const def=localDateISO(min);
 const slotOptions=date=>{const sch=DB.getDoctorSchedule(a.doctorId,date); if(!d.available||!sch||sch.available===false||(d.leaveDates||[]).includes(date))return []; return (sch.slots||[]).filter(t=>!DB.appointments.some(x=>x.id!==id&&x.doctorId===a.doctorId&&x.date===date&&x.time===t&&x.status!=='cancelled'));};
 openModal('Reschedule appointment',`<div class="alert info">Choose a new date and available time for ${esc(a.id)}.</div><div class="form-grid"><label>Date<input id="rsDate" type="date" min="${def}" value="${a.date>=def?a.date:def}"></label><label>Available time<select id="rsTime"></select></label></div>`,`<button class="small-btn" data-close>Cancel</button><button class="primary-btn" id="saveReschedule">Save new time</button>`);
 const fill=()=>{const slots=slotOptions($('#rsDate').value);$('#rsTime').innerHTML=slots.map(t=>`<option value="${t}">${fmtTime(t)}</option>`).join('')||'<option value="">No available time</option>';}; $('#rsDate').onchange=fill; fill();
 $('#saveReschedule').onclick=()=>{const date=$('#rsDate').value,time=$('#rsTime').value;if(!time)return toast('No available time for this date','error');if(!slotOptions(date).includes(time))return toast('Selected slot is no longer available','error');const paid=a.paymentStatus==='paid';DB.updateAppointment(id,{date,time,status:paid?'confirmed':'pending',paymentStatus:paid?'paid':'unpaid',paymentMethod:paid?a.paymentMethod:'',paymentRef:paid?a.paymentRef:'',paymentProof:paid?a.paymentProof||'':''});markRecordActioned('appointments',id);DB.addNotification({userId:state.user.id,title:'Appointment rescheduled',message:`${a.id} moved to ${fmtDate(date)} at ${fmtTime(time)}.`});closeModal();toast('Appointment rescheduled ✓');render();};
}
function openReview(id){
 const a=DB.appointments.find(x=>x.id===id); if(!a)return;
 if(state.user.role!=='patient'||a.patientId!==state.user.patientId)return toast('Only the patient can review this appointment','error');
 if(a.status!=='completed')return toast('Only completed appointments can be reviewed','error');
 if(DB.reviews.some(r=>r.appointmentId===id))return toast('This appointment already has a review','error');
 const d=DB.getDoctor(a.doctorId);
 openModal('Rate your consultation',`<div class="doctor-profile-mini">${avatar(d,'doc-avatar')}<div><b>${esc(d?.name||'Doctor')}</b><small>${esc(d?.specialty||'')}</small></div></div><div class="form-grid"><label>Rating<select id="reviewRating"><option value="5">★★★★★ 5</option><option value="4">★★★★☆ 4</option><option value="3">★★★☆☆ 3</option><option value="2">★★☆☆☆ 2</option><option value="1">★☆☆☆☆ 1</option></select></label><label class="full-col">Comment<textarea id="reviewComment" rows="4" placeholder="Share your experience"></textarea></label></div>`,`<button class="small-btn" data-close>Cancel</button><button class="primary-btn" id="saveReview">Submit review</button>`);
 $('#saveReview').onclick=()=>{const rating=Number($('#reviewRating').value),comment=$('#reviewComment').value.trim();DB.addReview({appointmentId:id,patientId:state.user.patientId,doctorId:a.doctorId,rating,comment});markRecordActioned('appointments',id);DB.addNotification({userId:state.user.id,title:'Review submitted',message:`Thanks for reviewing ${d?.name||'your doctor'}.`});closeModal();toast('Review submitted ✓');render();};
}
function openModal(title,body,foot){$('#modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-head"><h3>${title}</h3><button class="close-btn" data-close>×</button></div><div class="modal-body">${body}</div><div class="modal-foot">${foot}</div></div></div>`;$$('[data-close]').forEach(b=>b.onclick=closeModal)}function closeModal(){$('#modalRoot').innerHTML=''}
